import{_ as r,C as i,o as a,c as o,ag as s,E as n}from"./chunks/framework.cyF4XceO.js";const g=JSON.parse('{"title":"Versions and compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"docs/versions.md","filePath":"docs/versions.md"}'),d={name:"docs/versions.md"};function l(c,e,h,p,m,u){const t=i("StatusNote");return a(),o("div",null,[e[0]||(e[0]=s(`<h1 id="versions-and-compatibility" tabindex="-1">Versions and compatibility <a class="header-anchor" href="#versions-and-compatibility" aria-label="Permalink to &quot;Versions and compatibility&quot;">​</a></h1><p>Takoform keeps four current version streams: the Host API, each Form definition, Core/library software, and Provider software. A version on one axis is not a pre-release label for another axis. Historical numbered documents are not a fifth current stream.</p><h2 id="current-design-target" tabindex="-1">Current design target <a class="header-anchor" href="#current-design-target" aria-label="Permalink to &quot;Current design target&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Axis</th><th>Current identity</th><th>Meaning and availability</th></tr></thead><tbody><tr><td>Host API</td><td><strong><code>forms.takoform.com/v1</code></strong></td><td>Stable wire contract for discovery, exact Form availability, operations, fencing, and errors.</td></tr><tr><td>Form</td><td>each Form&#39;s <strong>definitionVersion</strong></td><td>Exact independently versioned contract; the official catalog has 31 Experimental Forms in eight families.</td></tr><tr><td>Core/library</td><td>independent software SemVer</td><td>SDK, verifier, compiler, and CLI releases; they do not change the Host API or Form identity.</td></tr><tr><td>Provider</td><td><strong>3.0.0, Registry-published</strong></td><td>Software tooling with typed mappings for official Forms only; Provider SemVer is independent of every Form and Host API.</td></tr></tbody></table><p>The current Form Package format identifier is <code>packages.forms.takoform.com/v1alpha5</code>. It versions a data envelope, not the Takoform product or its API.</p><p>The canonical <code>registry.terraform.io/tako0614/takoform</code> address publishes the official Provider mappings for official Forms only. Independent third parties may distribute Forms under their own namespaces through the same package and verification path; each Provider build must explicitly support the FormRefs it exposes. A module can combine multiple Takoform Providers with industry-standard providers, so the Takoform Provider is software tooling rather than one universal infrastructure provider.</p><p><strong>Provider 3.0.0</strong> is the current Registry-published implementation. <strong>Provider 2.1.1</strong>, <strong>Provider 2.0.0</strong>, and <strong>Provider 1.0.3</strong> remain installable Registry history for earlier epochs (<a href="/spec/decisions/0042-the-pre-beta-epochs-are-withdrawn.html">decision 0042</a>); (<a href="/release/migrations/v2-to-v3.html">v2 to v3 migration boundary</a>).</p><h2 id="published-compatibility-mapping" tabindex="-1">Published compatibility mapping <a class="header-anchor" href="#published-compatibility-mapping" aria-label="Permalink to &quot;Published compatibility mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Client or distribution</th><th>Host API</th><th>Forms and definitions</th><th>Status / use</th></tr></thead><tbody><tr><td>Provider 3.0.0 distribution</td><td>Host API v1</td><td>8 versionless families; 31 current Experimental Form identities</td><td>Current Registry-published non-normative reference implementation.</td></tr><tr><td>Provider 2.1.1 distribution</td><td>Host API v1beta1</td><td>Edge Form Family v1beta1; 15 immutable historical Form identities</td><td>Registry-published retained client; descriptor remains <code>candidate-only</code> metadata by design.</td></tr><tr><td>Provider 2.0.0 distribution</td><td>Host API v1alpha2 (withdrawn epoch)</td><td>The nine withdrawn v1alpha2 Forms</td><td>Immutable Registry history; exact-pin only, no successors.</td></tr><tr><td>Provider 1.0.3 Legacy</td><td>Host API v1alpha1 (withdrawn epoch)</td><td>The withdrawn v1 Form Package identities</td><td>Immutable Registry history; recovery and migration only.</td></tr></tbody></table><p>The current Host API v1 contract and versionless Form families are not interchangeable labels. A Form&#39;s own definition SemVer does not change Provider SemVer, and a historical Specification receipt does not silently mint Form <code>1.0.0</code> identities or an API v1.1 route.</p><h2 id="current-edge-reference-family-16-experimental-forms" tabindex="-1">Current Edge reference family (16 Experimental Forms) <a class="header-anchor" href="#current-edge-reference-family-16-experimental-forms" aria-label="Permalink to &quot;Current Edge reference family (16 Experimental Forms)&quot;">​</a></h2><p>The current Edge family is versionless and contains these 16 exact Experimental <code>0.x</code> Forms:</p><ul><li><a href="/docs/resources/module_worker.html"><code>takoform_module_worker</code></a></li><li><a href="/docs/resources/worker_bundle.html"><code>takoform_worker_bundle</code></a></li><li><a href="/docs/resources/static_asset_bundle.html"><code>takoform_static_asset_bundle</code></a></li><li><a href="/docs/resources/worker_version.html"><code>takoform_worker_version</code></a></li><li><a href="/docs/resources/worker_deployment.html"><code>takoform_worker_deployment</code></a></li><li><a href="/docs/resources/worker_custom_domain.html"><code>takoform_worker_custom_domain</code></a></li><li><a href="/docs/resources/worker_endpoint.html"><code>takoform_worker_endpoint</code></a></li><li><a href="/docs/resources/worker_cron_trigger.html"><code>takoform_worker_cron_trigger</code></a></li><li><a href="/docs/resources/edge_kv_namespace.html"><code>takoform_edge_kv_namespace</code></a></li><li><a href="/docs/resources/sqlite_database.html"><code>takoform_sqlite_database</code></a></li><li><a href="/docs/resources/sqlite_migration_set.html"><code>takoform_sqlite_migration_set</code></a></li><li><a href="/docs/resources/sqlite_migration_application.html"><code>takoform_sqlite_migration_application</code></a></li><li><a href="/docs/resources/at_least_once_queue.html"><code>takoform_at_least_once_queue</code></a></li><li><a href="/docs/resources/queue_consumer.html"><code>takoform_queue_consumer</code></a></li><li><a href="/docs/resources/durable_workflow.html"><code>takoform_durable_workflow</code></a></li><li><a href="/docs/resources/actor_namespace.html"><code>takoform_actor_namespace</code></a></li></ul><p>The independent Registry-published Provider 3 uses these resource names without making them normative or changing Form maturity:</p><div class="language-hcl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">hcl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">terraform</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  required_providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    takoform</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      source  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;registry.terraform.io/tako0614/takoform&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      version </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&gt;= 3.0.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Provider 2.1.1 remains available for the exact historical identities it shipped; it must not be read as implementing the current 31-Form corpus.</p><h2 id="withdrawn-epochs" tabindex="-1">Withdrawn epochs <a class="header-anchor" href="#withdrawn-epochs" aria-label="Permalink to &quot;Withdrawn epochs&quot;">​</a></h2><p>The pre-Beta epochs and their documentation were withdrawn (<a href="/spec/decisions/0042-the-pre-beta-epochs-are-withdrawn.html">decision 0042</a>). The withdrawn resource pages no longer exist on this site; the identities are recorded as retired in the published ledgers, and the bytes stay in the repository&#39;s git history and release tags. Existing users of the withdrawn resources keep an exact pin (<code>= 2.0.0</code> or <code>= 2.1.1</code>, <code>= 1.0.3</code> for v1 state) or follow the <a href="/release/migrations/v2-to-v3.html">v2 to v3 migration boundary</a>: stay pinned, remove from state, or destroy while still pinned. Nothing is migrated automatically, and upgrading past the withdrawal with one of the nine still in state fails closed before any lifecycle request.</p>`,18)),n(t)])}const k=r(d,[["render",l]]);export{g as __pageData,k as default};
